"""`harness carry-forward` — manage deferred items recorded in per-feature state.

Carry-forward items are deferred work (manual TCs, accepted risks, scope-creep
findings with ADR). They live in `docs/features/<id>/state.json` at
`.pending_carry_forward[]` (P-tier per `docs/state/SCHEMA.md`) and are
populated by:

- `/arh-plan-implementation` Phase 3 risk-table `accepted (adr)` cells (kind=risk)
- `/arh-validate-feature` Phase 5 manual TCs with no recorded result (kind=test_case)
- `/arh-review` Phase 4 scope-creep findings with `accepted (adr)` (kind=finding)
- `/arh-human-review` Phase 2 flags with status=defer (kind=finding)

This CLI lets the user inventory + resolve them. Resolution requires an evidence
path (e.g. screenshot, log file, ADR link) so the resolution is auditable.

Read-only state mutation; no LLM calls; deterministic.
"""

from __future__ import annotations

import json
from datetime import datetime
from pathlib import Path
from typing import Any

from rich.console import Console
from rich.table import Table

_FEATURES_DIR = Path("docs") / "features"
_console = Console()
_err = Console(stderr=True)


def cmd_carry_forward_list(*, feature: str | None) -> int:
    """List all pending carry-forward items across (or per) feature."""
    records = _load_all_features(feature_filter=feature)
    if records is None:
        return 1

    rows: list[tuple[str, dict[str, Any]]] = []
    for fid, record in records.items():
        for item in record.get("pending_carry_forward", []):
            if item.get("resolved_at"):
                continue  # show only unresolved
            rows.append((fid, item))

    if not rows:
        _console.print("[dim]no pending carry-forward items[/dim]")
        return 0

    tbl = Table(show_header=True, header_style="bold", title="Pending carry-forward")
    tbl.add_column("Feature")
    tbl.add_column("Item id")
    tbl.add_column("Kind")
    tbl.add_column("Reason")
    tbl.add_column("Added")
    tbl.add_column("Owner")

    for fid, item in rows:
        tbl.add_row(
            fid,
            item.get("item_id", "<unset>"),
            item.get("kind", "<unset>"),
            (item.get("reason") or "")[:60],
            (item.get("added_at") or "")[:10],
            item.get("owner") or "<unset>",
        )
    _console.print(tbl)
    _console.print(f"\n[dim]{len(rows)} pending[/dim]")
    return 0


def cmd_carry_forward_show(*, item_id: str) -> int:
    """Print full details for one carry-forward item."""
    records = _load_all_features()
    if records is None:
        return 1

    for fid, record in records.items():
        for item in record.get("pending_carry_forward", []):
            if item.get("item_id") == item_id:
                _console.print(f"[bold]Feature:[/bold] {fid}")
                _console.print(json.dumps(item, indent=2, default=str))
                return 0

    _err.print(f"[red]carry-forward item {item_id!r} not found[/red]")
    return 1


def cmd_carry_forward_resolve(*, item_id: str, evidence: str) -> int:
    """Mark a carry-forward item resolved with evidence path."""
    records = _load_all_features()
    if records is None:
        return 1

    for fid, record in records.items():
        for item in record.get("pending_carry_forward", []):
            if item.get("item_id") == item_id:
                if item.get("resolved_at"):
                    _err.print(f"[yellow]item {item_id!r} already resolved at {item['resolved_at']}[/yellow]")
                    return 1
                item["resolved_at"] = _now_iso()
                item["evidence"] = evidence
                _write_feature_state(fid, record)
                _console.print(f"[green]resolved[/green] {item_id} — evidence: {evidence}")
                return 0

    _err.print(f"[red]carry-forward item {item_id!r} not found[/red]")
    return 1


def cmd_carry_forward_defer(*, item_id: str, until: str) -> int:
    """Defer a carry-forward item by setting a future `until` field.

    Used when the team accepts pushing a manual TC / risk to a later sprint.
    The item stays pending; the until field gives a visible target so it doesn't
    silently rot.
    """
    records = _load_all_features()
    if records is None:
        return 1

    # Validate until date format (YYYY-MM-DD).
    try:
        datetime.strptime(until, "%Y-%m-%d")
    except ValueError:
        _err.print(f"[red]--until must be YYYY-MM-DD; got {until!r}[/red]")
        return 1

    for fid, record in records.items():
        for item in record.get("pending_carry_forward", []):
            if item.get("item_id") == item_id:
                item["deferred_until"] = until
                _write_feature_state(fid, record)
                _console.print(f"[yellow]deferred[/yellow] {item_id} → {until}")
                return 0

    _err.print(f"[red]carry-forward item {item_id!r} not found[/red]")
    return 1


# ---- helpers ----

def _features_root() -> Path:
    return Path.cwd() / _FEATURES_DIR


def _load_all_features(
    *, feature_filter: str | None = None
) -> dict[str, dict[str, Any]] | None:
    """Load every `docs/features/<id>/state.json` keyed by feature id.

    pending_carry_forward[] is P-tier — lives only in per-feature files.
    """
    root = _features_root()
    if not root.exists():
        _err.print(f"[red]features dir not found at {root}[/red]")
        _err.print("[dim]run from a project root with .claude/ initialised; per-feature dirs are created at /arh-plan-requirements[/dim]")
        return None

    records: dict[str, dict[str, Any]] = {}
    for child in sorted(root.iterdir()):
        if not child.is_dir():
            continue
        if feature_filter and child.name != feature_filter:
            continue
        state_path = child / "state.json"
        if not state_path.exists():
            continue
        try:
            records[child.name] = json.loads(state_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError as exc:
            _err.print(f"[red]state file invalid JSON at {state_path}: {exc}[/red]")
            return None
    return records


def _write_feature_state(fid: str, record: dict[str, Any]) -> None:
    state_path = _features_root() / fid / "state.json"
    state_path.write_text(json.dumps(record, indent=2, default=str) + "\n", encoding="utf-8")


def _now_iso() -> str:
    return datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
